changeSet.sql:
CREATE OR REPLACE TRIGGER trg_usuario_historico_inmutable
BEFORE UPDATE OR DELETE ON usuario_historico
BEGIN
    RAISE_APPLICATION_ERROR(-20001, 'El histórico es inmutable');
END;

DECLARE
    v_admin     NUMBER;
    v_user      NUMBER;
    v_t0        TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    v_t1        TIMESTAMP;
    v_t2        TIMESTAMP;
    v_t3        TIMESTAMP;
    v_total     NUMBER;
    v_sin_traza NUMBER;
    v_desorden  NUMBER;
    v_solape    NUMBER;
    v_alias     NUMBER;
    v_primero   VARCHAR2(32);

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    v_t1 := v_t0 + INTERVAL '1' HOUR;
    v_t2 := v_t0 + INTERVAL '2' HOUR;
    v_t3 := v_t0 + INTERVAL '3' HOUR;

    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 902);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);

    MERGE INTO cat_motivo_desactivacion d
    USING (SELECT 'BAJA_EMPRESA' AS reason_code FROM dual) s
       ON (d.reason_code = s.reason_code)
    WHEN NOT MATCHED THEN
        INSERT (reason_code, reason_name, is_active)
        VALUES ('BAJA_EMPRESA', 'Baja en la empresa', 'Y');

    INSERT INTO usuario (full_name, corporate_email, role_code, status)
         VALUES ('Oraculo Administrador', 'oraculo.tsk050.admin@example.invalid', 'ADMINISTRADOR', 'ACTIVO')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, role_code, status, created_at, created_by)
         VALUES ('Oraculo Empleado', 'oraculo.tsk050.empleado@example.invalid', 'EMPLEADO', 'ACTIVO', v_t0, v_admin)
      RETURNING user_id INTO v_user;

    -- 1) Alta como EMPLEADO: abre la primera asignacion de rol y no cierra ninguna anterior.
    INSERT INTO usuario_historico (user_id, change_type, previous_role_code, new_role_code, valid_from, valid_to, changed_by, changed_at)
         VALUES (v_user, 'ROL', NULL, 'EMPLEADO', v_t0, NULL, v_admin, v_t0);

    -- 2) Cambio a TECNICO_MANTENIMIENTO: cierra la asignacion anterior (valid_to) en el MISMO
    --    instante en que abre la nueva (valid_from).
    INSERT INTO usuario_historico (user_id, change_type, previous_role_code, new_role_code, valid_from, valid_to, changed_by, changed_at)
         VALUES (v_user, 'ROL', 'EMPLEADO', 'TECNICO_MANTENIMIENTO', v_t1, v_t1, v_admin, v_t1);
    UPDATE usuario SET role_code = 'TECNICO_MANTENIMIENTO', role_changed_at = v_t1, role_changed_by = v_admin
     WHERE user_id = v_user;

    -- 3) Desactivacion con motivo obligatorio.
    INSERT INTO usuario_historico (user_id, change_type, previous_status, new_status, reason_code, note, valid_from, changed_by, changed_at)
         VALUES (v_user, 'ESTADO', 'ACTIVO', 'INACTIVO', 'BAJA_EMPRESA', 'Baja del oraculo de TSK-050', v_t2, v_admin, v_t2);
    UPDATE usuario SET status = 'INACTIVO', deactivated_at = v_t2, deactivated_by = v_admin,
                       deactivation_reason_code = 'BAJA_EMPRESA'
     WHERE user_id = v_user;

    -- 4) Reactivacion: sin motivo, el histórico de la baja permanece.
    INSERT INTO usuario_historico (user_id, change_type, previous_status, new_status, valid_from, changed_by, changed_at)
         VALUES (v_user, 'ESTADO', 'INACTIVO', 'ACTIVO', v_t3, v_admin, v_t3);
    UPDATE usuario SET status = 'ACTIVO', deactivated_at = NULL, deactivated_by = NULL,
                       deactivation_reason_code = NULL
     WHERE user_id = v_user;

    SELECT COUNT(*) INTO v_total FROM usuario_historico WHERE user_id = v_user;
    IF v_total <> 4 THEN
        RAISE_APPLICATION_ERROR(-20900, 'ORACULO AC-ROL-05: se esperaban 4 entradas de historico y hay ' || v_total);
    END IF;

    SELECT COUNT(*) INTO v_sin_traza FROM usuario_historico
     WHERE user_id = v_user AND (changed_by IS NULL OR changed_at IS NULL);
    IF v_sin_traza <> 0 THEN
        RAISE_APPLICATION_ERROR(-20901, 'ORACULO AC-ROL-05: hay ' || v_sin_traza || ' entradas sin actor o sin fecha');
    END IF;

    SELECT COUNT(*) INTO v_desorden FROM (
        SELECT changed_at,
               LAG(changed_at) OVER (ORDER BY changed_at DESC, history_id DESC) AS mas_reciente
          FROM usuario_historico
         WHERE user_id = v_user)
     WHERE mas_reciente IS NOT NULL AND mas_reciente <= changed_at;
    IF v_desorden <> 0 THEN
        RAISE_APPLICATION_ERROR(-20902, 'ORACULO AC-USU-04: el historico no es ordenable por changed_at descendente');
    END IF;

    SELECT new_value INTO v_primero FROM (
        SELECT new_value FROM usuario_historico
         WHERE user_id = v_user
         ORDER BY changed_at DESC, history_id DESC)
     WHERE ROWNUM = 1;
    IF v_primero <> 'ACTIVO' THEN
        RAISE_APPLICATION_ERROR(-20903, 'ORACULO AC-USU-04: la entrada mas reciente deberia ser la reactivacion y es ' || v_primero);
    END IF;

    SELECT COUNT(*) INTO v_alias FROM usuario_historico
     WHERE user_id = v_user
       AND (event_type <> change_type
         OR NVL(new_value, '~') <> NVL(COALESCE(new_role_code, new_status), '~')
         OR NVL(previous_value, '~') <> NVL(COALESCE(previous_role_code, previous_status), '~'));
    IF v_alias <> 0 THEN
        RAISE_APPLICATION_ERROR(-20904, 'ORACULO T.5 ARC-116: las columnas virtuales no reflejan las fisicas en ' || v_alias || ' entradas');
    END IF;

    SELECT COUNT(*) INTO v_solape
      FROM (SELECT user_id,
                   valid_from AS vigente_desde,
                   LEAD(valid_to) OVER (PARTITION BY user_id ORDER BY valid_from, history_id) AS vigente_hasta
              FROM usuario_historico
             WHERE change_type = 'ROL') a
      JOIN (SELECT user_id,
                   valid_from AS vigente_desde,
                   LEAD(valid_to) OVER (PARTITION BY user_id ORDER BY valid_from, history_id) AS vigente_hasta
              FROM usuario_historico
             WHERE change_type = 'ROL') b
        ON b.user_id = a.user_id
       AND b.vigente_desde > a.vigente_desde
       AND (a.vigente_hasta IS NULL OR a.vigente_hasta > b.vigente_desde);
    IF v_solape <> 0 THEN
        RAISE_APPLICATION_ERROR(-20905, 'ORACULO REQ-005 RN-02: hay ' || v_solape || ' solapamientos de asignacion de rol');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
